select json_build_object(
'taken_at', now(),
'server_version', current_setting('server_version'),
'regclass_checks', json_build_object('contest_groups', to_regclass('public.contest_groups')::text,'hole_scores', to_regclass('public.hole_scores')::text,'contest_rounds', to_regclass('public.contest_rounds')::text,'contest_games', to_regclass('public.contest_games')::text),
'columns', (select json_agg(json_build_object('table',table_name,'col',column_name,'pos',ordinal_position,'type',data_type,'udt',udt_name,'nullable',is_nullable,'default',column_default) order by table_name,ordinal_position) from information_schema.columns where table_schema='public'),
'constraints', (select json_agg(json_build_object('table',c.conrelid::regclass::text,'name',c.conname,'domain',case when c.contypid<>0 then format_type(c.contypid,null) end,'def',pg_get_constraintdef(c.oid),'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred,'local',c.conislocal,'inheritance_count',c.coninhcount,'parent',(select pc.conrelid::regclass::text||':'||pc.conname from pg_constraint pc where pc.oid=c.conparentid),'noinherit',c.connoinherit) order by c.conrelid::regclass::text,c.conname) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public' ),
'indexes', (select json_agg(json_build_object('table',tablename,'name',indexname,'def',indexdef) order by tablename,indexname) from pg_indexes where schemaname='public'),
'policies', (select json_agg(json_build_object('schemaname',schemaname,'tablename',tablename,'policyname',policyname,'permissive',permissive,'roles',roles,'cmd',cmd,'qual',qual,'with_check',with_check) order by tablename,policyname) from pg_policies where schemaname='public'),
'rls', (select json_agg(json_build_object('table',relname,'rls',relrowsecurity,'force',relforcerowsecurity) order by relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p')),
'functions', (select json_agg(json_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'def',case when p.prokind<>'a' then pg_get_functiondef(p.oid) end,'secdef',p.prosecdef,'config',p.proconfig,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'volatility',p.provolatile,'leakproof',p.proleakproof,'parallel',p.proparallel,'return_type',format_type(p.prorettype,null),'returns_set',p.proretset,'argument_defaults_count',p.pronargdefaults,'argument_defaults',pg_get_expr(p.proargdefaults,0),'cost',p.procost,'rows',p.prorows,'language',(select lanname from pg_language where oid=p.prolang),'transforms',(select json_agg(format_type(t,null) order by ord) from unnest(p.protrftypes) with ordinality v(t,ord)),'kind',p.prokind,'strict',p.proisstrict,'support',p.prosupport::text) order by p.proname, pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' ),
'triggers', (select json_agg(json_build_object('schema',n.nspname,'table',c.relname,'name',case when t.tgisinternal then (select conname from pg_constraint where oid=t.tgconstraint)||':'||t.tgfoid::regproc::text||':'||t.tgtype::text else t.tgname end,'internal',t.tgisinternal,'enabled',t.tgenabled,'def',case when t.tgisinternal then replace(pg_get_triggerdef(t.oid),quote_ident(t.tgname),'internal_constraint_trigger') else pg_get_triggerdef(t.oid) end) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname='public' or (n.nspname='auth' and exists(select 1 from pg_proc p join pg_namespace pn on pn.oid=p.pronamespace where p.oid=t.tgfoid and pn.nspname='public')))),
'views', (select json_agg(json_build_object('name',viewname,'def',definition,'owner',viewowner) order by viewname) from pg_views where schemaname='public'),
'grants', (select json_agg(json_build_object('table',table_name,'grantee',grantee,'priv',privilege_type) order by table_name,grantee,privilege_type) from information_schema.role_table_grants where table_schema='public'),
'routine_grants', (select json_agg(json_build_object('routine',routine_name,'grantee',grantee,'priv',privilege_type) order by routine_name,grantee) from information_schema.routine_privileges where routine_schema='public'),
'publication', (select json_agg(json_build_object('pub',pubname,'schema',schemaname,'table',tablename) order by pubname,tablename) from pg_publication_tables),
'extensions', (select json_agg(json_build_object('name',extname,'version',extversion,'schema',extnamespace::regnamespace::text,'relocatable',extrelocatable,'extension_config',(select json_agg(v::regclass::text order by ord) from unnest(extconfig) with ordinality a(v,ord)),'extension_condition',extcondition) order by extname) from pg_extension),
'owners', (select json_agg(json_build_object('name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p','v','m','S')),
'default_acls', (select json_agg(json_build_object('role',pg_get_userbyid(d.defaclrole),'schema',d.defaclnamespace::regnamespace::text,'objtype',d.defaclobjtype,'acl',d.defaclacl::text)) from pg_default_acl d),
'types', (select json_agg(json_build_object('name',t.typname,'kind',t.typtype,'base',format_type(t.typbasetype,t.typtypmod),'notnull',t.typnotnull,'default',t.typdefault,'collation',t.typcollation::regcollation::text,'owner',pg_get_userbyid(t.typowner),'acl',t.typacl::text,'labels',(select json_agg(enumlabel order by enumsortorder) from pg_enum e where e.enumtypid=t.oid)) order by t.typname) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typtype in ('e','d','c') and not exists(select 1 from pg_class c where c.reltype=t.oid)),
'identity_generated', (select json_agg(json_build_object('table',c.relname,'col',a.attname,'identity',a.attidentity,'generated',a.attgenerated)) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and a.attnum>0 and not a.attisdropped and (a.attidentity<>'' or a.attgenerated<>'')),
'reloptions', (select json_agg(json_build_object('name',c.relname,'options',c.reloptions)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.reloptions is not null),
'sequences', (select json_agg(json_build_object('name',c.relname,'type',format_type(s.seqtypid,null),'start',s.seqstart::text,'min',s.seqmin::text,'max',s.seqmax::text,'inc',s.seqincrement,'cycle',s.seqcycle,'cache',s.seqcache)) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
'seq_deps', (select json_agg(json_build_object('seq',s.relname,'table',c.relname,'col',d.refobjsubid,'deptype',d.deptype)) from pg_depend d join pg_class s on s.oid=d.objid join pg_namespace n on n.oid=s.relnamespace join pg_class c on c.oid=d.refobjid where n.nspname='public' and s.relkind='S' and d.classid='pg_class'::regclass and d.refclassid='pg_class'::regclass and d.deptype in ('a','i')),
'schema_acl', (select json_build_object('owner',pg_get_userbyid(nspowner),'acl',nspacl::text) from pg_namespace where nspname='public'),
'column_acls', (select json_agg(json_build_object('table',c.relname,'col',a.attname,'acl',a.attacl::text)) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and a.attnum>0 and not a.attisdropped and a.attacl is not null),
'event_triggers', (select json_agg(json_build_object('name',e.evtname,'event',e.evtevent,'fn_schema',n.nspname,'fn',p.proname,'owner',pg_get_userbyid(e.evtowner),'enabled',e.evtenabled,'tags',e.evttags)) from pg_event_trigger e join pg_proc p on p.oid=e.evtfoid join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' or pg_get_userbyid(e.evtowner) not in ('supabase_admin','supabase_auth_admin','supabase_storage_admin','supabase_realtime_admin')),
'column_definitions', (select json_agg(json_build_object('table',c.relname,'col',a.attname,'type',format_type(a.atttypid,a.atttypmod),'type_schema',tn.nspname,'collation',case when a.attcollation<>t.typcollation then a.attcollation::regcollation::text end,'dimensions',a.attndims,'local',a.attislocal,'inheritance_count',a.attinhcount,'statistics_target',a.attstattarget,'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'generated',a.attgenerated,'identity',a.attidentity,'storage',a.attstorage,'compression',a.attcompression,'options',a.attoptions,'fdw_options',a.attfdwoptions) order by c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace join pg_type t on t.oid=a.atttypid join pg_namespace tn on tn.oid=t.typnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname='public' and a.attnum>0 and not a.attisdropped),
'relation_behavior', (select json_agg(json_build_object('name',c.relname,'kind',c.relkind,'persistence',c.relpersistence,'replica_identity',c.relreplident,'partition',c.relispartition,'partition_key',case when c.relkind='p' then pg_get_partkeydef(c.oid) end,'partition_bound',pg_get_expr(c.relpartbound,c.oid),'access_method',am.amname,'tablespace',ts.spcname,'populated',c.relispopulated,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'of_type',case when c.reloftype<>0 then format_type(c.reloftype,null) end,'check_count',c.relchecks) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace left join pg_am am on am.oid=c.relam left join pg_tablespace ts on ts.oid=c.reltablespace where n.nspname='public'),
'index_behavior', (select json_agg(json_build_object('name',c.relname,'replica_identity',i.indisreplident,'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'clustered',i.indisclustered,'nulls_not_distinct',i.indnullsnotdistinct,'immediate',i.indimmediate,'exclusion',i.indisexclusion)) from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
'publication_behavior', (select json_agg(json_build_object('name',p.pubname,'owner',pg_get_userbyid(p.pubowner),'insert',p.pubinsert,'update',p.pubupdate,'delete',p.pubdelete,'truncate',p.pubtruncate,'alltables',p.puballtables,'viaroot',p.pubviaroot) order by p.pubname) from pg_publication p),
'publication_relations', (select json_agg(json_build_object('pub',p.pubname,'table',r.prrelid::regclass::text,'column_list',(select json_agg(a.attname order by k.ord) from unnest(r.prattrs) with ordinality k(num,ord) join pg_attribute a on a.attrelid=r.prrelid and a.attnum=k.num),'filter',pg_get_expr(r.prqual,r.prrelid))) from pg_publication_rel r join pg_publication p on p.oid=r.prpubid),
'publication_schemas', (select json_agg(json_build_object('pub',p.pubname,'schema',n.nspname)) from pg_publication_namespace pn join pg_publication p on p.oid=pn.pnpubid join pg_namespace n on n.oid=pn.pnnspid),
'inheritance', (select json_agg(json_build_object('child',i.inhrelid::regclass::text,'parent',i.inhparent::regclass::text,'sequence',i.inhseqno,'detach_pending',i.inhdetachpending)) from pg_inherits i join pg_class c on c.oid=i.inhrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' or exists(select 1 from pg_class pc join pg_namespace pn on pn.oid=pc.relnamespace where pc.oid=i.inhparent and pn.nspname='public')),
'rules', (select json_agg(json_build_object('table',c.relname,'name',r.rulename,'enabled',r.ev_enabled,'def',pg_get_ruledef(r.oid))) from pg_rewrite r join pg_class c on c.oid=r.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
'extended_statistics', (select json_agg(json_build_object('name',s.stxname,'owner',pg_get_userbyid(s.stxowner),'target',s.stxstattarget,'def',pg_get_statisticsobjdef(s.oid))) from pg_statistic_ext s join pg_namespace n on n.oid=s.stxnamespace where n.nspname='public'),
'ranges', (select json_agg(json_build_object('name',t.typname,'subtype',format_type(r.rngsubtype,null),'collation',r.rngcollation::regcollation::text,'opclass',(select ns.nspname||'.'||oc.opcname from pg_opclass oc join pg_namespace ns on ns.oid=oc.opcnamespace where oc.oid=r.rngsubopc),'canonical',r.rngcanonical::text,'subdiff',r.rngsubdiff::text,'multirange',format_type(r.rngmultitypid,null))) from pg_range r join pg_type t on t.oid=r.rngtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public'),
'foreign_tables', (select json_agg(json_build_object('table',c.relname,'server',s.srvname,'options',f.ftoptions,'server_type',s.srvtype,'server_version',s.srvversion,'server_options',s.srvoptions,'wrapper',w.fdwname,'handler',w.fdwhandler::regproc::text,'validator',w.fdwvalidator::regproc::text)) from pg_foreign_table f join pg_class c on c.oid=f.ftrelid join pg_namespace n on n.oid=c.relnamespace join pg_foreign_server s on s.oid=f.ftserver join pg_foreign_data_wrapper w on w.oid=s.srvfdw where n.nspname='public'),
'aggregates', (select json_agg(json_build_object('function',p.oid::regprocedure::text,'kind',a.aggkind,'direct_args',a.aggnumdirectargs,'transition',a.aggtransfn::text,'final',a.aggfinalfn::text,'combine',a.aggcombinefn::text,'serialize',a.aggserialfn::text,'deserialize',a.aggdeserialfn::text,'moving_transition',a.aggmtransfn::text,'moving_inverse',a.aggminvtransfn::text,'moving_final',a.aggmfinalfn::text,'final_extra',a.aggfinalextra,'moving_final_extra',a.aggmfinalextra,'final_modify',a.aggfinalmodify,'moving_final_modify',a.aggmfinalmodify,'sort_operator',a.aggsortop::regoperator::text,'transition_type',format_type(a.aggtranstype,null),'transition_space',a.aggtransspace,'moving_type',format_type(a.aggmtranstype,null),'moving_space',a.aggmtransspace,'initial',a.agginitval,'moving_initial',a.aggminitval)) from pg_aggregate a join pg_proc p on p.oid=a.aggfnoid join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
'type_behavior', (select json_agg(json_build_object('name',t.typname,'owner',pg_get_userbyid(t.typowner),'acl',t.typacl::text,'kind',t.typtype,'length',t.typlen,'byval',t.typbyval,'category',t.typcategory,'preferred',t.typispreferred,'defined',t.typisdefined,'delimiter',t.typdelim,'subscript',t.typsubscript::text,'element',format_type(t.typelem,null),'input',t.typinput::text,'output',t.typoutput::text,'receive',t.typreceive::text,'send',t.typsend::text,'typmodin',t.typmodin::text,'typmodout',t.typmodout::text,'analyze',t.typanalyze::text,'alignment',t.typalign,'storage',t.typstorage,'notnull',t.typnotnull,'base',format_type(t.typbasetype,t.typtypmod),'dimensions',t.typndims,'collation',t.typcollation::regcollation::text,'default',pg_get_expr(t.typdefaultbin,0))) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typcategory<>'A'),
'unreviewed_schemas', (select json_agg(json_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text)) from pg_namespace where nspname !~ '^pg_' and nspname not in ('public','information_schema','auth','extensions','supabase_migrations','storage','realtime','_realtime','graphql','graphql_public','vault','supabase_functions','net','pgbouncer','pgsodium','pgsodium_masks','cron','pgmq','pgmq_public','_analytics','_supavisor')),
'app_roles', (select json_agg(json_build_object('name',r.rolname,'super',r.rolsuper,'inherit',r.rolinherit,'createrole',r.rolcreaterole,'createdb',r.rolcreatedb,'login',r.rolcanlogin,'replication',r.rolreplication,'bypassrls',r.rolbypassrls) order by r.rolname) from pg_roles r where r.rolname in ('anon','authenticated','service_role','authenticator')),
'app_role_memberships', (select json_agg(json_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) order by pg_get_userbyid(m.roleid),pg_get_userbyid(m.member)) from pg_auth_members m where pg_get_userbyid(m.member) in ('anon','authenticated','service_role','authenticator') or pg_get_userbyid(m.roleid) in ('anon','authenticated','service_role','authenticator')),
'migrations', (select json_agg(json_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations)
) as catalog;
